INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.65.0',
  '2026-08-04',
  'Закреплённый заголовок больше не сбрасывается + общий выключатель для всех страниц',
  E'Настройка «закрепить заголовок при прокрутке» переехала из памяти браузера на сервер, поэтому она больше не пропадает и одинакова везде — в Telegram, в веб-версии и в расширении.\n\nВ Настройках появился общий выключатель «Закрепить заголовок на всех страницах»: не нужно отмечать каждую страницу отдельно. Когда он включён, в настройках конкретной страницы это видно и написано, откуда управлять.\n\nИз настроек страниц убрана устаревшая надпись «индивидуальные настройки страницы пока не имеются» — закрепление заголовка есть у любой страницы, и надпись ей противоречила.',
  E'Причина сброса: настройка жила ТОЛЬКО в localStorage — Telegram чистит хранилище WebView, а у веб-версии и расширения оно вообще своё (ровно та же история, что с темой до v2.61).\n\nМиграция 0074: user_settings.pinned_pages JSONB (имена роутов) + pin_all_headers BOOLEAN. API GET|PUT /settings/headers — отдельная пара ручек, а не часть appearance: у appearance запись зависит от вида сессии (Telegram против токена), а закрепление общее для всех режимов входа, мешать их в одном обработчике значит напрашиваться на ошибку. Валидация: не больше 64 страниц, отсев пустых, длинных и дублей.\n\nФронтенд: shared/pinnedHeader.ts — сервер источник истины, localStorage остался кэшем для первого кадра (иначе прыгала бы вёрстка); loadPinnedHeaders() при старте рядом с loadAppearance(). Запись оптимистичная, но при ошибке изменение откатывается и показывается тост — молчаливое проглатывание ошибки давало бы ту же жалобу «настройка сбрасывается».\n\nОбщий выключатель вынесен отдельной секцией Settings, а не в «Оформление»: в браузере блок «Оформление» подписан «на Telegram не влияет», а эта настройка общая. isHeaderPinned() = pin_all ИЛИ страница в списке; в модалке страницы при включённом pin_all чекбокс отмечен и заблокирован с пояснением, точечные отметки сохраняются.\n\nПроверено: API (умолчания, запись, чтение, чистка мусора, 400 на >64 страниц) и в браузере — очистка localStorage с перезагрузкой восстанавливает состояние с сервера и заново наполняет кэш.'
);
-- +goose StatementEnd

